arguments.command:
cd /tmp/coreclr_work
# Those are ARM mapping symbols ($d = data). Let me try with function symbols only
nm -C --defined-only libcoreclr.debug 2>/dev/null | grep -i " [tT] " | awk '{print $1, $2, $3}' | sort | awk '
BEGIN { prev_addr=""; prev_name="" }
{
  if ($1 > "000000000018df6c" && prev_addr != "" && found1 == 0) { 
    print "0x0018df6c is in: " prev_name " (at " prev_addr ")"; found1=1 
  }
  if ($1 > "000000000018e3a4" && prev_addr != "" && found2 == 0) { 
    print "0x0018e3a4 is in: " prev_name " (at " prev_addr ")"; found2=1 
  }
  prev_addr=$1; prev_name=$3
}' 2>/dev/null

